public class StatementCalculator {
    public double calculateAmount(Play play, Performance performance) {
        switch (play.getType()) {
            case "tragedy":
                return 40000 + (performance.getAudience() > 30 ? 1000 * (performance.getAudience() - 30) : 0);
            case "comedy":
                return 30000 + (performance.getAudience() > 20 ? 10000 + 500 * (performance.getAudience() - 20) : 0) + 300 * performance.getAudience();
            default:
                throw new IllegalArgumentException("Unknown play type: " + play.getType());
        }
    }

    public int calculateVolumeCredits(Play play, Performance performance) {
        int credits = 0;
        switch (play.getType()) {
            case "tragedy":
                credits += Math.max(performance.getAudience() - 30, 0);
                break;
            case "comedy":
                credits += Math.max(performance.getAudience() - 30, 0);
                credits += performance.getAudience() / 5;
                break;
        }
        return credits;
    }
}

public class StatementFormatter {
    public String formatStatement(Invoice invoice, Map<String, Play> plays, StatementCalculator calculator) {
        double totalAmount = 0;
        int totalCredits = 0;
        StringBuilder result = new StringBuilder("Statement for " + invoice.getCustomer() + "\n");

        for (Performance performance : invoice.getPerformances()) {
            Play play = plays.get(performance.getPlayID());
            if (play == null) {
                throw new IllegalArgumentException("Unknown play: " + performance.getPlayID());
            }
            double thisAmount = calculator.calculateAmount(play, performance);
            totalAmount += thisAmount;
            totalCredits += calculator.calculateVolumeCredits(play, performance);
            result.append(String.format(" %s: %s (%d seats)\n",
                    play.getName(), NumberFormat.getCurrencyInstance(Locale.US).format(thisAmount / 100),
                    performance.getAudience()));
        }

        result.append(String.format("Amount owed is %s\n",
                NumberFormat.getCurrencyInstance(Locale.US).format(totalAmount / 100)));
        result.append(String.format("You earned %d credits\n", totalCredits));
        return result.toString();
    }
}

public class Main {
    public static void main(String[] args) {
        Map<String, Play> plays = Map.of(
                "hamlet", new Play("Hamlet", "tragedy"),
                "as like", new Play("As You Like It", "comedy"),
                "othello", new Play("Othello", "tragedy")
        );

        Invoice invoice = new Invoice("BigCo", List.of(
                new Performance("hamlet", 55),
                new Performance("as like", 35),
                new Performance("othello", 40)));

        StatementCalculator calculator = new StatementCalculator();
        StatementFormatter formatter = new StatementFormatter();
        System.out.println(formatter.formatStatement(invoice, plays, calculator));
    }
}
